window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a01ac9917d1bac09"]={"versions": [{"id": "FIG-a01ac9917d1bac09", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenmapping-Diagramm aus der AUTOSAR E2E-Library-Spezifikation (SWS E2ELibrary). Das Diagramm veranschaulicht die Abbildung von Software-Datenelementen (z. B. aus der Anwendungs- oder SWC-Ebene) in das Byte- und Bit-Layout einer Interaktionsschicht-PDU (I-PDU) für die serielle Datenübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Quell-Datenelemente / Variablen</strong>:</li>\n<li><code>speed</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU verwendet werden (<code>/<em> 16-bit, but 12 bits used in I-PDU</em>/</code>).</li>\n<li><code>accel</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU verwendet werden (<code>/<em> 16-bit, but 12 bits used in I-PDU</em>/</code>).</li>\n<li><strong>I-PDU-Byte-Struktur</strong>:</li>\n<li>Linear angeordnetes Byte-Array (repräsentiert durch die segmentierten Blöcke).</li>\n<li>Enthaltene Segmente und Nutzlastfelder:</li>\n<li>Nicht näher spezifizierte bzw. reservierte/Padding-Bereiche (orange hinterlegte Felder).</li>\n<li><code>accel</code>-Feld: Eingebetteter 12-Bit-Wert innerhalb der PDU-Bytes.</li>\n<li><code>speed</code>-Feld: Eingebetteter 12-Bit-Wert, der sich über Bytegrenzen erstreckt.</li>\n<li>Freies Feld / Datenfeld ohne Beschriftung.</li>\n<li>Konstantes/vorbelegtes Byte <code>0xF0</code>.</li>\n<li>Konstantes/vorbelegtes Byte <code>0xFF</code>.</li>\n<li><strong>Zuordnungspfeile</strong>: Gerichtete Linien von den Typdeklarationen auf die exakte Position innerhalb des I-PDU-Puffers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Mapping ohne dynamische Zustandsübergänge. Vor dem Versand oder der E2E-Prüfung serialisiert der Kommunikationsstack (z. B. COM-Modul bzw. E2E-Transformator) die Datenelemente <code>speed</code> und <code>accel</code>, indem er die signifikanten 12 Bits der jeweiligen 16-Bit-Variablen an die definierten Bit- und Byte-Offsets der Ziel-I-PDU mappt und mit statischen Werten (<code>0xF0</code>, <code>0xFF</code>) sowie weiteren PDU-Segmenten kombiniert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Bit- und Byte-Alignment-Beispiel für Integratoren und Entwickler zur korrekten Konfiguration des Signal-Mappings und der PDU-Serialisierung. Verdeutlicht, dass Datenelemente mit abweichender Bitbreite (12 Bits Nutzsignal in 16-Bit-Container) nicht zwingend bündig an 8-Bit- oder 16-Bit-Grenzen ausgerichtet sein müssen, sondern positionsgenau in die I-PDU gepackt werden. Für E2E-Schutzmechanismen (CRC-Berechnung und Counter) ist die exakte Byte-Reihenfolge und Bit-Positionierung im PDU-Puffer zwingend konsistent auf Sender- und Empfängerseite einzuhalten.</p>"}, {"id": "FIG-7e018289546df3bf", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenmapping-Diagramm aus der AUTOSAR E2E-Library-Spezifikation (SWS E2ELibrary). Das Diagramm veranschaulicht die Abbildung von Software-Datenelementen (z. B. aus der Anwendungs- oder SWC-Ebene) in das Byte- und Bit-Layout einer Interaktionsschicht-PDU (I-PDU) für die serielle Datenübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Quell-Datenelemente / Variablen</strong>:</li>\n<li><code>speed</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU verwendet werden (<code>/<em> 16-bit, but 12 bits used in I-PDU</em>/</code>).</li>\n<li><code>accel</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU verwendet werden (<code>/<em> 16-bit, but 12 bits used in I-PDU</em>/</code>).</li>\n<li><strong>I-PDU-Byte-Struktur</strong>:</li>\n<li>Linear angeordnetes Byte-Array (repräsentiert durch die segmentierten Blöcke).</li>\n<li>Enthaltene Segmente und Nutzlastfelder:</li>\n<li>Nicht näher spezifizierte bzw. reservierte/Padding-Bereiche (orange hinterlegte Felder).</li>\n<li><code>accel</code>-Feld: Eingebetteter 12-Bit-Wert innerhalb der PDU-Bytes.</li>\n<li><code>speed</code>-Feld: Eingebetteter 12-Bit-Wert, der sich über Bytegrenzen erstreckt.</li>\n<li>Freies Feld / Datenfeld ohne Beschriftung.</li>\n<li>Konstantes/vorbelegtes Byte <code>0xF0</code>.</li>\n<li>Konstantes/vorbelegtes Byte <code>0xFF</code>.</li>\n<li><strong>Zuordnungspfeile</strong>: Gerichtete Linien von den Typdeklarationen auf die exakte Position innerhalb des I-PDU-Puffers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Mapping ohne dynamische Zustandsübergänge. Vor dem Versand oder der E2E-Prüfung serialisiert der Kommunikationsstack (z. B. COM-Modul bzw. E2E-Transformator) die Datenelemente <code>speed</code> und <code>accel</code>, indem er die signifikanten 12 Bits der jeweiligen 16-Bit-Variablen an die definierten Bit- und Byte-Offsets der Ziel-I-PDU mappt und mit statischen Werten (<code>0xF0</code>, <code>0xFF</code>) sowie weiteren PDU-Segmenten kombiniert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Bit- und Byte-Alignment-Beispiel für Integratoren und Entwickler zur korrekten Konfiguration des Signal-Mappings und der PDU-Serialisierung. Verdeutlicht, dass Datenelemente mit abweichender Bitbreite (12 Bits Nutzsignal in 16-Bit-Container) nicht zwingend bündig an 8-Bit- oder 16-Bit-Grenzen ausgerichtet sein müssen, sondern positionsgenau in die I-PDU gepackt werden. Für E2E-Schutzmechanismen (CRC-Berechnung und Counter) ist die exakte Byte-Reihenfolge und Bit-Positionierung im PDU-Puffer zwingend konsistent auf Sender- und Empfängerseite einzuhalten.</p>"}], "trans": [{"from": "FIG-a01ac9917d1bac09", "to": "FIG-7e018289546df3bf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
